#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/homebrew/tasks/brew-casks.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Install/upgrade casks and VS Code extensions from the Brewfile"
# MISE hide=true
# MISE dir="~"
# MISE tools={uv="latest", python="3.14"}

# Run by hand. Formulae and most casks are mise's: [mise.bootstrap.packages] in
# tools.toml, generated into conf.d/<tool>/mise.toml. The Brewfile only holds
# casks and VS Code extensions, so cleanup is scoped to those types and never
# touches formulae.

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402

BREWFILE = os.path.expanduser("~/.config/brewfile")


def run(*cmd):
  """Run the command. When it fails, stop the task with its code, as set -e
  does. A missing command gives 127, as in the shell."""
  sys.stdout.flush()
  try:
    rc = subprocess.run(cmd, check=False).returncode
  except FileNotFoundError:
    print(f"{cmd[0]}: command not found", file=sys.stderr, flush=True)
    sys.exit(127)
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def main():
  helpers.print_header("Installing/upgrading casks from the Brewfile ...")
  run("brew", "bundle", "install", "--upgrade", "--file", BREWFILE)

  helpers.print_header("Removing casks and extensions NOT in the Brewfile ...")
  run("brew", "bundle", "cleanup", "--force", "--casks", "--vscode", "--file", BREWFILE)


if __name__ == "__main__":
  main()
